namespace KclLib.Tests;

using System.Text;
using System.Text.Json;
using Google.Protobuf;
using KclLib.API;
using Microsoft.VisualStudio.TestTools.UnitTesting;

/// <summary>
/// Cross-language consistency runner: executes the hermetic cases from
/// tests/consistency/cases.json (generated by tests/consistency/generate_cases.py)
/// and asserts the same golden expectations as every other language runner.
///
/// NOTE: written but not executed in this environment (no dotnet SDK installed).
/// Run with: dotnet test --filter ConsistencyTest
/// </summary>
[TestClass]
public class ConsistencyTest
{
    static readonly JsonSerializerOptions JsonOptions = new() { PropertyNameCaseInsensitive = true };
    static readonly Lazy<(string Path, JsonDocument Doc)> Manifest = new(LoadManifest);
    static readonly Lazy<API> ApiInstance = new(() => new API());
    static readonly Lazy<HashSet<string>> AvailableMethods = new(LoadMethods);

    static string RepoRoot
    {
        get
        {
            // Tests run with the CWD somewhere under bin/<config>/<tfm>/; walk
            // up to the KclLib.Tests project directory, then two levels to the
            // repository root (mirrors APITest.FindCsprojInParentDirectory).
            var dir = new DirectoryInfo(Environment.CurrentDirectory);
            while (dir != null && dir.GetFiles("*.csproj").Length == 0)
            {
                dir = dir.Parent;
            }
            return dir?.Parent?.Parent?.FullName
                ?? throw new InvalidOperationException("could not locate repository root");
        }
    }

    static (string, JsonDocument) LoadManifest()
    {
        var path = Path.Combine(RepoRoot, "tests", "consistency", "cases.json");
        Assert.IsTrue(
            File.Exists(path),
            $"consistency manifest not found at {path}. Run `python tests/consistency/generate_cases.py` to generate it.");
        var doc = JsonDocument.Parse(File.ReadAllText(path));
        Assert.AreEqual(1, doc.RootElement.GetProperty("version").GetInt32(), "unsupported manifest version");
        return (path, doc);
    }

    /// <summary>
    /// Determine the available RPC surface once per run. Cores that predate
    /// BuiltinService.ListMethod answer with an empty list (or throw), in
    /// which case new_core cases are skipped.
    /// </summary>
    static HashSet<string> LoadMethods()
    {
        var methods = new HashSet<string>();
        try
        {
            foreach (var name in ApiInstance.Value.ListMethod().MethodNameList)
            {
                methods.Add(name);
            }
        }
        catch
        {
            // treat the RPC surface as unknown
        }
        return methods;
    }

    static JsonElement FindCase(string name)
    {
        foreach (var c in Manifest.Value.Doc.RootElement.GetProperty("cases").EnumerateArray())
        {
            if (c.GetProperty("name").GetString() == name)
            {
                return c;
            }
        }
        Assert.Fail($"consistency case not found in manifest: {name}");
        return default;
    }

    static void Skip(string reason)
    {
        // MSTest has no dynamic skip; inconclusive keeps the run green while
        // recording the skip reason in the test output.
        Assert.Inconclusive(reason);
    }

    static string Diff(string expected, string actual)
    {
        var el = expected.Split('\n');
        var al = actual.Split('\n');
        var n = Math.Max(el.Length, al.Length);
        var sb = new StringBuilder("--- expected\n+++ actual\n");
        for (var i = 0; i < n; i++)
        {
            var e = i < el.Length ? el[i] : null;
            var a = i < al.Length ? al[i] : null;
            if (e != null && e == a)
            {
                sb.Append("  ").Append(e).Append('\n');
            }
            else
            {
                if (e != null)
                {
                    sb.Append("- ").Append(e).Append('\n');
                }
                if (a != null)
                {
                    sb.Append("+ ").Append(a).Append('\n');
                }
            }
        }
        return sb.ToString();
    }

    static void AssertField(string caseName, string field, string expected, string actual)
    {
        Assert.AreEqual(
            expected,
            actual,
            $"consistency case `{caseName}` field `{field}` mismatch:\n{Diff(expected, actual)}");
    }

    static void RunCase(string name)
    {
        var c = FindCase(name);
        var rpc = c.GetProperty("rpc").GetString()!;
        var newCore = c.GetProperty("new_core").GetBoolean();
        var args = c.GetProperty("args");
        var expect = c.GetProperty("expect");

        switch (rpc)
        {
            case "KclService.Ping":
            {
                var result = ApiInstance.Value.Ping(new PingArgs { Value = args.GetProperty("value").GetString() });
                AssertField(name, "value", expect.GetProperty("value").GetString()!, result.Value);
                break;
            }
            case "KclService.ExecProgram":
            {
                var execArgs = new ExecProgramArgs();
                foreach (var code in args.GetProperty("k_code_list").EnumerateArray())
                {
                    execArgs.KCodeList.Add(code.GetString());
                }
                if (args.TryGetProperty("overrides", out var overrides))
                {
                    foreach (var o in overrides.EnumerateArray())
                    {
                        execArgs.Overrides.Add(o.GetString());
                    }
                }
                var result = ApiInstance.Value.ExecProgram(execArgs);
                if (expect.TryGetProperty("yaml_result", out var yaml))
                {
                    AssertField(name, "yaml_result", yaml.GetString()!, result.YamlResult);
                }
                if (expect.TryGetProperty("json_result", out var json))
                {
                    AssertField(name, "json_result", json.GetString()!, result.JsonResult);
                }
                break;
            }
            case "KclService.FormatCode":
            {
                var result = ApiInstance.Value.FormatCode(new FormatCodeArgs { Source = args.GetProperty("source").GetString() });
                AssertField(name, "formatted", expect.GetProperty("formatted").GetString()!, result.Formatted.ToStringUtf8());
                break;
            }
            case "KclService.ValidateCode":
            {
                var result = ApiInstance.Value.ValidateCode(new ValidateCodeArgs
                {
                    Code = args.GetProperty("code").GetString(),
                    Data = args.GetProperty("data").GetString(),
                });
                Assert.AreEqual(
                    expect.GetProperty("success").GetBoolean(),
                    result.Success,
                    $"consistency case `{name}` field `success`");
                if (expect.TryGetProperty("err_message", out var errMessage))
                {
                    AssertField(name, "err_message", errMessage.GetString()!, result.ErrMessage);
                }
                break;
            }
            case "KclService.FormatTestReport":
            {
                if (newCore && !AvailableMethods.Value.Contains(rpc))
                {
                    Skip($"core does not list {rpc} (old core)");
                }
                var reportArgs = new FormatTestReportArgs { Result = new KclLib.API.TestResult() };
                foreach (var info in args.GetProperty("result").GetProperty("info").EnumerateArray())
                {
                    reportArgs.Result.Info.Add(new TestCaseInfo
                    {
                        Name = info.GetProperty("name").GetString(),
                        Error = info.TryGetProperty("error", out var e) ? e.GetString() : "",
                        // uint64 values are canonical proto JSON strings in the manifest.
                        Duration = ulong.Parse(info.GetProperty("duration").GetString()!),
                        LogMessage = info.TryGetProperty("log_message", out var l) ? l.GetString() : "",
                    });
                }
                var result = ApiInstance.Value.FormatTestReport(reportArgs);
                AssertField(name, "report", expect.GetProperty("report").GetString()!, result.Report);
                break;
            }
            case "KclService.GenerateToml":
            {
                if (newCore && !AvailableMethods.Value.Contains(rpc))
                {
                    Skip($"core does not list {rpc} (old core)");
                }
                var tomlArgs = new GenerateTomlArgs { ExecArgs = new ExecProgramArgs() };
                foreach (var code in args.GetProperty("exec_args").GetProperty("k_code_list").EnumerateArray())
                {
                    tomlArgs.ExecArgs.KCodeList.Add(code.GetString());
                }
                var result = ApiInstance.Value.GenerateToml(tomlArgs);
                AssertField(name, "toml", expect.GetProperty("toml").GetString()!, result.Toml);
                break;
            }
            case "KclService.GenerateKcl":
            {
                if (newCore && !AvailableMethods.Value.Contains(rpc))
                {
                    Skip($"core does not list {rpc} (old core)");
                }
                var result = ApiInstance.Value.GenerateKcl(new GenerateKclArgs
                {
                    Source = args.GetProperty("source").GetString(),
                    Filename = args.GetProperty("filename").GetString(),
                    Format = args.GetProperty("format").GetString(),
                });
                AssertField(name, "kcl", expect.GetProperty("kcl").GetString()!, result.Kcl);
                break;
            }
            case "KclService.GenerateOpenAPI":
            {
                if (newCore && !AvailableMethods.Value.Contains(rpc))
                {
                    Skip($"core does not list {rpc} (old core)");
                }
                var result = ApiInstance.Value.GenerateOpenAPI(new GenerateOpenAPIArgs
                {
                    ParseArgs = ParseArgs(args.GetProperty("parse_args")),
                    Version = args.TryGetProperty("version", out var v) ? v.GetString() : "",
                });
                AssertField(name, "spec", expect.GetProperty("spec").GetString()!, result.Spec);
                break;
            }
            case "KclService.GenerateProto":
            {
                if (newCore && !AvailableMethods.Value.Contains(rpc))
                {
                    Skip($"core does not list {rpc} (old core)");
                }
                var result = ApiInstance.Value.GenerateProto(new GenerateProtoArgs
                {
                    ParseArgs = ParseArgs(args.GetProperty("parse_args")),
                    Package = args.TryGetProperty("package", out var p) ? p.GetString() : "",
                });
                AssertField(name, "proto", expect.GetProperty("proto").GetString()!, result.Proto);
                break;
            }
            case "KclService.GenerateDoc":
            {
                if (newCore && !AvailableMethods.Value.Contains(rpc))
                {
                    Skip($"core does not list {rpc} (old core)");
                }
                var result = ApiInstance.Value.GenerateDoc(new GenerateDocArgs
                {
                    ParseArgs = ParseArgs(args.GetProperty("parse_args")),
                    Format = args.TryGetProperty("format", out var f) ? f.GetString() : "",
                });
                AssertField(name, "content", expect.GetProperty("content").GetString()!, result.Content);
                break;
            }
            default:
                Assert.Fail($"no runner support for rpc {rpc}");
                break;
        }
    }

    /// <summary>
    /// Build <see cref="ParseProgramArgs"/> from the manifest. Path entries are
    /// pinned repo-relative by generate_cases.py; they are resolved against the
    /// repository root (the parent of the directory holding cases.json), while
    /// absolute entries are kept as-is.
    /// </summary>
    static ParseProgramArgs ParseArgs(JsonElement node)
    {
        var parseArgs = new ParseProgramArgs();
        foreach (var path in node.GetProperty("paths").EnumerateArray())
        {
            var p = path.GetString()!;
            parseArgs.Paths.Add(Path.IsPathRooted(p) ? p : Path.Combine(RepoRoot, p));
        }
        if (node.TryGetProperty("sources", out var sources))
        {
            foreach (var source in sources.EnumerateArray())
            {
                parseArgs.Sources.Add(source.GetString());
            }
        }
        return parseArgs;
    }

    [TestMethod]
    public void TestPing() => RunCase("ping");

    [TestMethod]
    public void TestExecProgramBasic() => RunCase("exec_program_basic");

    [TestMethod]
    public void TestExecProgramOverrides() => RunCase("exec_program_overrides");

    [TestMethod]
    public void TestFormatCode() => RunCase("format_code");

    [TestMethod]
    public void TestValidateCodeOk() => RunCase("validate_code_ok");

    [TestMethod]
    public void TestValidateCodeInvalid() => RunCase("validate_code_invalid");

    [TestMethod]
    public void TestGenerateKclJson() => RunCase("generate_kcl_json");

    [TestMethod]
    public void TestGenerateKclYaml() => RunCase("generate_kcl_yaml");

    [TestMethod]
    public void TestGenerateToml() => RunCase("generate_toml");

    [TestMethod]
    public void TestFormatTestReport() => RunCase("format_test_report");

    [TestMethod]
    public void TestGenerateOpenAPIV3() => RunCase("generate_openapi_v3");

    [TestMethod]
    public void TestGenerateProto() => RunCase("generate_proto");

    [TestMethod]
    public void TestGenerateDocMd() => RunCase("generate_doc_md");
}
